                    return
                end

                cachedResultLabel = nil

                local quality, percent =
                    readItemState(item, true)

                local textValue = quality or "Unknown"

                if percent ~= nil then
                    textValue = textValue
                        .. string.format(
                            " (%+.2f%%)",
                            percent
                        )
                end

                notify(
                    "Reforge State",
                    textValue,
                    5
                )

                M.UpdateStatus()
            end

            local function runWorker()
                if busy or not ctx.Config.AutoReforge then
                    return
                end

                busy = true
                attempts = 0
                M.UpdateStatus()

                task.spawn(function()
                    local remotes =
                        ctx.ReplicatedStorage
                            :FindFirstChild("Remotes")
                    local upgradeRemote =
                        remotes
                        and remotes:FindFirstChild("Upgrade")

                    if not upgradeRemote
                        or not upgradeRemote:IsA(
                            "RemoteFunction"
                        ) then

                        ctx.Config.AutoReforge = false
                        busy = false
                        save()
                        M.UpdateStatus()
                        return
                    end

                    local maxAttempts = math.clamp(
                        tonumber(
                            ctx.Config.ReforgeMaxAttempts
                        ) or 100,
                        1,
                        500
                    )

                    local unknownReads = 0

                    while ctx.Config.AutoReforge
                        and attempts < maxAttempts do

                        local item = selectedItem()

                        if not item or not item.Parent then
                            break
                        end

                        local goalMet, quality, percent =
                            goalState(item)

                        if goalMet then
                            break
                        end

                        if quality or percent ~= nil then
                            unknownReads = 0
                        end

                        attempts = attempts + 1
                        M.UpdateStatus()

                        local ok = pcall(function()
                            upgradeRemote:InvokeServer(
                                "Reforge",
                                item
                            )
                        end)

                        if not ok then
                            task.wait(0.75)
                            break
                        end

                        -- Let the game's result label update.
