                        M.UpdateStatus()

                        local _, afterQuality, afterPercent =
                            goalState(item)

                        if not afterQuality
                            or afterPercent == nil then

                            unknownReads = unknownReads + 1

                            if unknownReads >= 3 then
                                break
                            end
                        else
                            unknownReads = 0
                        end

