                    end

                    ctx.Config.AutoReforge = false
                    busy = false
                    save()
                    M.UpdateStatus()
                end)
            end

            function M.Toggle(value)
                ctx.Config.AutoReforge =
                    value == true

                save()
                M.UpdateStatus()

                if not value then
                    return
                end

                local item = selectedItem()

                if not item then
                    ctx.Config.AutoReforge = false
                    save()

