                end
            end

            function M.StartStatusLoop()
                task.spawn(function()
                    while true do
                        task.wait(
                            ctx.Config.AutoReforge
                            and 0.35
                            or 1.00
                        )
                        M.UpdateStatus()
                    end
                end)
            end

            M.Qualities = qualities

            return M
        end
